class Permissions:
    def __init__(self):
        self.roles = {
            "viewer": {"read": True, "write": False},
            "editor": {"read": True, "write": True},
        }
        self.inheritance_chain = {}

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        return self.roles[role].get(action, False)

    def define_role(self, name, actions, inherits=None):
        if name in self.roles:
            raise ValueError(f"Role '{name}' already exists")
        self.roles[name] = actions
        if inherits:
            self.inheritance_chain[name] = inherits
        self._resolve_inheritance()

    def _resolve_inheritance(self):
        for role, inherits in self.inheritance_chain.items():
            if inherits not in self.roles:
                raise ValueError(f"Inheritance '{inherits}' for role '{role}' does not exist")
            inherited_actions = self.roles[inherits]
            for action, value in inherited_actions.items():
                if action not in self.roles[role]:
                    self.roles[role][action] = value
                elif self.roles[role][action]!= value:
                    raise ValueError(f"Conflict in action '{action}' for role '{role}'")
