class Permissions:
    def __init__(self):
        self.roles = {
            "viewer": {"actions": ["read"], "inherits": None},
            "editor": {"actions": ["read", "write"], "inherits": "viewer"},
        }

    def allowed(self, role, action):
        current_role = role
        while current_role:
            if action in self.roles.get(current_role, {}).get("actions", []):
                return True
            if self.roles.get(current_role, {}).get("inherits"):
                current_role = self.roles.get(current_role, {}).get("inherits")
            else:
                current_role = None
        return False

