class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }
        self.inheritance_chain = {}

    def allowed(self, role, action):
        if role in self.permissions:
            return action in self.permissions[role]
        return False

    def define_role(self, name, actions, inherits=None):
        if inherits:
            if inherits not in self.inheritance_chain:
                self.inheritance_chain[inherits] = self.resolve_inheritance(inherits)
            self.permissions[name] = list(set(self.inheritance_chain[inherits] + actions))
        else:
            self.permissions[name] = actions

    def resolve_inheritance(self, role):
        result = []
        current_role = role
        while current_role in self.permissions:
            result.extend(self.permissions[current_role])
            if current_role in self.inheritance_chain:
                current_role = self.inheritance_chain[current_role][0]
            else:
                break
        return result
