class Permissions:
    def __init__(self):
        # Define the roles and their permissions
        self.permissions = {
            'viewer': {'read'},
            'editor': {'read', 'write'},
            'guest': set(),  # Guests have no permissions
        }

    def allowed(self, role, action):
        # Check if the role exists
        if role not in self.permissions:
            return False

        # Check if the action is allowed for the role
        allowed_actions = self.permissions[role]
        return action in allowed_actions

    def effective(self, role):
        # Return a detached set of permissions for the role
        return self.permissions.get(role, set())

    def restrict(self, role, allowed_actions):
        # Intersect current permissions with the supplied set
        return self.permissions.get(role, set()).intersection(allowed_actions)
