class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        # Check if the role exists in the permissions dictionary
        if role in self.permissions:
            # Check if the action is allowed for the role
            return self.permissions[role].get(action, False)
        else:
            # If the role is not recognized, deny the action
            return False

    def effective(self, role):
        # Check if the role exists in the permissions dictionary
        if role in self.permissions:
            # Return a set of allowed actions for the role
            return set(self.permissions[role].keys())
        else:
            # If the role is not recognized, return an empty set
            return set()

    def restrict(self, role, allowed_actions):
        # Check if the role exists in the permissions dictionary
        if role in self.permissions:
            # Intersect the current permissions with the supplied set
            self.permissions[role] = {action: value for action, value in self.permissions[role].items() if action in allowed_actions}
        else:
            # If the role is not recognized, do nothing
            pass
