class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }
        self.inheritance_tree = {}

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

    def define_role(self, name, actions, inherits=None):
        self.permissions[name] = actions
        if inherits:
            self.inheritance_tree[name] = inherits
        self.resolve_inheritance(name)

    def resolve_inheritance(self, role):
        if role in self.inheritance_tree:
            parent = self.inheritance_tree[role]
            if parent not in self.permissions:
                self.resolve_inheritance(parent)
            self.permissions[role].extend(self.permissions[parent])
            self.permissions[role] = list(set(self.permissions[role]))

