class Permissions:
    def __init__(self):
        self._permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }
        self._inherited_roles = {}

    def allowed(self, role, action):
        """
        Check if the given role is allowed to perform the specified action.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :param action: str, the action to check (e.g.,'read', 'write')
        :return: bool, True if the role is allowed to perform the action, otherwise False
        """
        if role not in self._permissions:
            if role in self._inherited_roles:
                return self.allowed(self._inherited_roles[role], action)
            return False
        return action in self._permissions[role]

    def define_role(self, name, actions, inherits=None):
        """
        Define a new role with the given name and actions.

        :param name: str, the name of the new role
        :param actions: dict, the actions allowed for the new role
        :param inherits: str, the name of the role to inherit from (optional)
        :return: None
        """
        self._permissions[name] = actions
        if inherits:
            self._inherited_roles[name] = inherits
            self._inherited_roles[inherits] = inherits
            while inherits in self._inherited_roles:
                inherits = self._inherited_roles[inherits]
            self._inherited_roles[name] = inherits

