class Permissions:
    def __init__(self):
        self._permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        """
        Check if the given role is allowed to perform the specified action.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :param action: str, the action to check (e.g.,'read', 'write')
        :return: bool, True if the role is allowed to perform the action, otherwise False
        """
        if role not in self._permissions:
            return False
        return action in self._permissions[role]

    def effective(self, role):
        """
        Return a set of actions that the given role is allowed to perform.

        :param role: str, the role to check (e.g., 'viewer', 'editor')
        :return: set, a set of actions that the role is allowed to perform
        """
        if role not in self._permissions:
            return set()
        return set(self._permissions[role].keys())

    def restrict(self, role, allowed_actions):
        """
        Intersect the current permissions of the given role with the supplied set of allowed actions.

        :param role: str, the role to restrict (e.g., 'viewer', 'editor')
        :param allowed_actions: set, a set of allowed actions
        :return: None
        """
        if role not in self._permissions:
            return
        self._permissions[role] = {action: self._permissions[role][action] for action in self._permissions[role] if action in allowed_actions}
