class Permissions:
    READ ='read'
    WRITE = 'write'

    def __init__(self):
        self.permissions = {
            'viewer': {self.READ},
            'editor': {self.READ, self.WRITE}
        }
        self.inheritance_chain = {}

    def define_role(self, name, actions, inherits=None):
        if inherits:
            if inherits not in self.inheritance_chain:
                self.inheritance_chain[inherits] = self.resolve_inheritance(inherits)
            actions = self.inheritance_chain[inherits].copy()
        self.permissions[name] = set(actions)

    def resolve_inheritance(self, role):
        result = set()
        stack = [role]
        while stack:
            current = stack.pop()
            result.update(self.permissions.get(current, set()))
            stack.extend(k for k in self.permissions if current in self.permissions[k])
        return result

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]
